import re

def parse_duration(s: str) -> int:
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, s)
    total = 0
    for num, unit in matches:
        n = int(num)
        if unit == 'h':
            total += n * 3600
        elif unit == 'm':
            total += n * 60
        elif unit == 's':
            total += n
